 const all=el('option','Complete city · all districts');all.value='all';$('city-district').replaceChildren(all,...worldNodes.filter(n=>n.district).map(n=>{const o=el('option',n.label);o.value=n.id;return o;}));$('city-district').value='all';const cityAll=el('option','Complete city');cityAll.value='all';$('city-topic-select').replaceChildren(cityAll,...worldNodes.filter(n=>n.district).map(n=>{const o=el('option',n.label);o.value=n.id;return o;}));$('city-topic-select').value='all';$('city-topic-select').addEventListener('change',()=>{$('city-district').value=$('city-topic-select').value;$('city-district').dispatchEvent(new Event('change'));});$('city-coverage').textContent=`${worldNodes.length} modeled elements · ${worldNodes.filter(n=>n.district).length} districts · ${courses.length} linked topics. Scope below lists simplifications.`;
 $('city-district').addEventListener('change',()=>{pause();const id=$('city-district').value;leaveLearning();$('city-topic-select').value=id;if(!failureKey){const journeys={'git-district':'city-git','delivery-district':'city-release','security-district':'city-security','iac-district':'city-iac','network-district':'city-network','data-district':'city-async','linux-district':'city-containers','observe-district':'city-observe','reliability-district':'city-recovery','cloud-district':'city-aws',cluster:'traffic'};if(journeys[id]){flowId=journeys[id];stepIndex=0;renderFlow();}}engine?.setDistrict(id==='all'?null:id);select(id==='all'?'environment':id,true);renderTree();});$('city-discovery').addEventListener('click',()=>{if(discoveredId){resetDistrict();select(discoveredId,true);}});$('city-restart').addEventListener('click',()=>{pause();goStep(0);});$('city-flow-select').replaceChildren(...Object.entries(worldFlows).map(([id,f])=>{const o=el('option',f.label);o.value=id;return o;}));$('city-flow-select').addEventListener('change',()=>{if(failureKey)return;$('world-flow').value=$('city-flow-select').value;$('world-flow').dispatchEvent(new Event('change'));});$('city-watch').addEventListener('click',()=>$('world-play').click());$('city-back').addEventListener('click',()=>$('world-prev').click());$('city-forward').addEventListener('click',()=>$('world-next').click());$('city-inspect').addEventListener('click',()=>{pause();select(flow().steps[stepIndex].to,true);});
